// tools/fw-bundler/src/catalog/index.js
/**
 * @fileoverview Generates `integrations/_shared/catalog.generated.json` — the
 * deterministic module-catalog artifact that replaces a live `scanAll`
 * re-scan at fw's own build/pack time (fw-tools-migration W1d, Option 3 —
 * see `ai/plans/fw-tools-mutualization/AMENDMENT-2026-07-23-integrations-decouple.md`).
 *
 * Ported semantics from `tools/fw-codegen/src/registry/index.js` (same
 * scan → render → write/--check shape), narrowed to just the scanner's
 * product : for each module, `name → { bindingName, subpath }` (subpath
 * POSIX-relative to `src/`, `.js` extension kept). No timestamp/version field
 * so the artifact is byte-idempotent across regenerations of an unchanged
 * source tree.
 *
 * Fail-closed: any unparseable module file aborts BOTH write and --check
 * modes with exit 1 and nothing written — same semantics fw's own
 * `integrations/_shared/core.js` has today (it throws on `unparseable.length`).
 *
 * Usage:
 *     bun cli.ts fw-bundler catalog                    # write the artifact
 *     bun cli.ts fw-bundler catalog --check             # exit 1 if out of date / missing
 *     bun cli.ts fw-bundler catalog --pkg <dir>         # target another package
 */

import { readFileSync, writeFileSync, existsSync, mkdirSync, renameSync, unlinkSync } from 'node:fs';
import { resolve, relative, join } from 'node:path';

import { scanAll } from '../modlib/scan-modules.js';
import { printHelp, wantsHelp, isMainModule } from '../modlib/cli-help.js';

// ─── Path-resolution seam ───
// Unlike `bundle`/`standalone`/`registry` (which default `--pkg` to `cwd()`,
// since fw's own build scripts run at the fw package root), `catalog` is
// invoked from the repo root via `bun cli.ts fw-bundler catalog` with no
// implied cwd — so its default targets `packages/front/fw` resolved from the
// REPO ROOT (this file's own location), not from `process.cwd()`.
const REPO_ROOT = resolve(import.meta.dir, '..', '..', '..', '..');
const DEFAULT_PKG = join(REPO_ROOT, 'packages', 'front', 'fw');

let PKG_ROOT, SRC_DIR, OUT_DIR, OUT_FILE;

function resolvePkgPaths(pkgRoot) {
    PKG_ROOT = pkgRoot;
    SRC_DIR = resolve(PKG_ROOT, 'src');
    OUT_DIR = resolve(PKG_ROOT, 'integrations', '_shared');
    OUT_FILE = resolve(OUT_DIR, 'catalog.generated.json');
}

// This comment lands verbatim in fw's SHIPPED `catalog.generated.json`, so it
// names the published `fw-bundler` bin — never the monorepo task router, which
// is not published. Pinned by `tests/catalog.test.ts`.
const CATALOG_COMMENT =
    'AUTO-GENERATED by `fw-bundler catalog` — do not edit. Regenerate after adding/renaming fw modules.';

// ─── CLI help ───
const HELP_USAGE = 'bun cli.ts fw-bundler catalog [--check] [--pkg <dir>]';
const HELP_FLAGS = [
    ['--check', 'Exit 1 (do not write) if integrations/_shared/catalog.generated.json is missing or out of date.'],
    ['--pkg <dir>', 'Package root to read from (default: packages/front/fw). Resolves src/ and integrations/_shared/ under it.'],
    ['--help, -h', 'Show this help.'],
];
const HELP_EXAMPLES = [
    'bun cli.ts fw-bundler catalog',
    'bun cli.ts fw-bundler catalog --check',
    'bun cli.ts fw-bundler catalog --pkg packages/front/fw',
];

/**
 * Parse the `catalog` subcommand argv.
 * @param {string[]} argv
 * @returns {{ check: boolean, pkg: string|null }}
 */
function parseArgs(argv) {
    const opts = { check: false, pkg: null };
    for (let i = 0; i < argv.length; i++) {
        const a = argv[i];
        if (a === '--check') opts.check = true;
        else if (a === '--pkg') opts.pkg = argv[++i];
        else if (a.startsWith('--')) throw new Error(`Unknown flag: ${a}. Run with --help.`);
        else throw new Error(`Unexpected positional argument: ${a}`);
    }
    return opts;
}

/**
 * Build the sorted `name -> { bindingName, subpath }` entries from a scan
 * result. Pure — no I/O.
 *
 * @param {Map<string, import('@awacloud/tool-fw-bundler/modlib').ModuleInfo>} byName
 * @returns {Array<[string, { bindingName: string, subpath: string }]>}
 */
function buildEntries(byName) {
    const names = [...byName.keys()].sort();
    return names.map((name) => {
        const info = byName.get(name);
        const subpath = relative(SRC_DIR, info.file).replace(/\\/g, '/');
        return [name, { bindingName: info.bindingName, subpath }];
    });
}

/**
 * Serialize catalog entries to the deterministic artifact text : 2-space
 * indent, lexicographically-sorted keys (entry order IS the JSON key order,
 * built manually rather than via `JSON.stringify` on a plain object — this
 * sidesteps JS's numeric-like-key reordering quirk for a guaranteed byte
 * layout), trailing newline, no timestamp/version field.
 *
 * @param {Array<[string, { bindingName: string, subpath: string }]>} entries
 * @returns {string}
 */
function serialize(entries) {
    const lines = [];
    lines.push('{');
    lines.push(`  "comment": ${JSON.stringify(CATALOG_COMMENT)},`);
    lines.push('  "modules": {');
    entries.forEach(([name, { bindingName, subpath }], i) => {
        const comma = i < entries.length - 1 ? ',' : '';
        lines.push(
            `    ${JSON.stringify(name)}: { "bindingName": ${JSON.stringify(bindingName)}, "subpath": ${JSON.stringify(subpath)} }${comma}`
        );
    });
    lines.push('  }');
    lines.push('}');
    return lines.join('\n') + '\n';
}

/**
 * Pure programmatic API: scan `<pkg>/src` and return the artifact text.
 * Never writes. Throws if any module file is unparseable.
 *
 * @param {string} [pkg]  Package root (default: packages/front/fw).
 * @returns {{ text: string, moduleCount: number }}
 */
export function renderCatalog(pkg = DEFAULT_PKG) {
    resolvePkgPaths(resolve(pkg));
    const { byName, unparseable } = scanAll(SRC_DIR);
    if (unparseable.length) {
        throw new Error(
            `[fw-bundler:catalog] ${unparseable.length} file(s) could not be parsed:\n  ` +
                unparseable.map((u) => u.file).join('\n  ')
        );
    }
    const entries = buildEntries(byName);
    return { text: serialize(entries), moduleCount: entries.length };
}

/**
 * Best-effort parse of a (possibly stale/foreign) catalog artifact's module
 * names, for the `--check` diff report. Never throws — an unparseable
 * current file is reported as "0 known modules", not a crash.
 *
 * @param {string} text
 * @returns {Record<string, { bindingName?: string, subpath?: string }>}
 */
function parseCurrentModules(text) {
    try {
        const obj = JSON.parse(text);
        return obj && typeof obj.modules === 'object' && obj.modules !== null ? obj.modules : {};
    } catch {
        return {};
    }
}

/**
 * Print what differs between the committed catalog and a fresh scan : missing
 * names (present on disk, absent from the fresh scan), added names (the
 * reverse), and changed names (same name, different bindingName/subpath).
 *
 * @param {string} currentText
 * @param {Array<[string, { bindingName: string, subpath: string }]>} nextEntries
 */
function printDiff(currentText, nextEntries) {
    const current = parseCurrentModules(currentText);
    const currentNames = new Set(Object.keys(current));
    const nextMap = new Map(nextEntries);
    const nextNames = new Set(nextMap.keys());

    const missing = [...currentNames].filter((n) => !nextNames.has(n)).sort();
    const added = [...nextNames].filter((n) => !currentNames.has(n)).sort();
    const changed = [...nextNames]
        .filter((n) => currentNames.has(n))
        .filter((n) => {
            const a = current[n] ?? {};
            const b = nextMap.get(n);
            return a.bindingName !== b.bindingName || a.subpath !== b.subpath;
        })
        .sort();

    if (missing.length) console.error(`  missing (no longer scanned): ${missing.join(', ')}`);
    if (added.length) console.error(`  added (new since committed): ${added.join(', ')}`);
    if (changed.length) console.error(`  changed (bindingName/subpath): ${changed.join(', ')}`);
    if (!missing.length && !added.length && !changed.length) {
        console.error('  (byte-level difference only — formatting or comment text changed)');
    }
}

/**
 * Run the `catalog` subcommand CLI. Returns the process exit code.
 * @param {string[]} argv  Args after the `catalog` token.
 * @returns {number}
 */
export function runCli(argv) {
    if (wantsHelp(argv)) { printHelp(HELP_USAGE, HELP_FLAGS, HELP_EXAMPLES); return 0; }

    let opts;
    try { opts = parseArgs(argv); }
    catch (err) { console.error('[fw-bundler:catalog] ' + err.message); return 2; }

    resolvePkgPaths(resolve(opts.pkg ?? DEFAULT_PKG));

    let byName, unparseable;
    try {
        ({ byName, unparseable } = scanAll(SRC_DIR));
    } catch (err) {
        console.error('[fw-bundler:catalog] ' + err.message);
        return 1;
    }
    if (unparseable.length) {
        console.error(
            `[fw-bundler:catalog] ${unparseable.length} file(s) could not be parsed:\n  ` +
                unparseable.map((u) => u.file).join('\n  ')
        );
        return 1;
    }

    const entries = buildEntries(byName);
    const next = serialize(entries);

    if (opts.check) {
        if (!existsSync(OUT_FILE)) {
            console.error('[fw-bundler:catalog] FAIL: file absent — run `bun cli.ts fw-bundler catalog`.');
            return 1;
        }
        const current = readFileSync(OUT_FILE, 'utf8');
        if (current === next) {
            console.log(`[fw-bundler:catalog] OK: catalog up to date (${entries.length} modules).`);
            return 0;
        }
        console.error('[fw-bundler:catalog] FAIL: catalog.generated.json is out of date.');
        printDiff(current, entries);
        return 1;
    }

    if (!existsSync(OUT_DIR)) mkdirSync(OUT_DIR, { recursive: true });

    // Atomic write: write to temp file in the same directory, then rename.
    // This prevents a reader from seeing partial JSON during the write.
    const tmpFile = OUT_FILE + '.tmp';
    try {
        writeFileSync(tmpFile, next, 'utf8');
        renameSync(tmpFile, OUT_FILE);
    } catch (err) {
        // Clean up temp file on error.
        try { unlinkSync(tmpFile); } catch { /* ignore */ }
        throw err;
    }

    console.log(
        `[fw-bundler:catalog] wrote ${relative(PKG_ROOT, OUT_FILE)} (${entries.length} modules).`
    );
    return 0;
}

if (isMainModule(import.meta.url)) {
    process.exit(runCli(process.argv.slice(2)));
}
